def normalise(reading_m: float) -> float:
    """Round a reading to two decimals, away from zero at the midpoint."""
    d = Decimal(str(reading_m))
    # ROUND_HALF_UP rounds half towards positive infinity, but we need
    # "away from zero" (half towards +/- infinity depending on sign).
    # So we round the absolute value with ROUND_HALF_UP, then restore sign.
    rounded = d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if rounded < 0:
        return float(-rounded)
    return float(rounded)

